1911	-- Run the aggregate-audio helper synchronously; returns (stdout, exitCode).
1912	local function runAudioHelper(...)
1913	    if not hs.fs.attributes(MEETING_HELPER_BIN) then return nil, -1 end
1914	    local args = { ... }
1915	    local quoted = {}
1916	    for _, a in ipairs(args) do table.insert(quoted, "'" .. tostring(a):gsub("'", "'\\''") .. "'") end
1917	    local cmd = "'" .. MEETING_HELPER_BIN .. "' " .. table.concat(quoted, " ")
1918	    local out, ok, _, code = hs.execute(cmd)
1919	    if out then out = out:gsub("%s+$", "") end
1920	    if ok then return out, 0 end
1921	    return out, code or -1
1922	end
