1956	-- Pick a sensible audible fallback output (anything that's not the
1957	-- aggregate and not BlackHole). Used when the user is stranded on the
1958	-- aggregate (e.g., a previous meeting got stuck and didn't restore).
1959	local function pickFallbackOutput()
1960	    local out, code = runAudioHelper("list")
1961	    if code ~= 0 or not out then return nil end
1962	    for line in out:gmatch("[^\n]+") do
1963	        local uid, name = line:match("^([^\t]+)\t(.+)$")
1964	        if uid and name
1965	           and uid ~= "com.local-whisper.aggregate-output"
1966	           and not name:find("BlackHole") then
1967	            return uid
1968	        end
1969	    end
1970	    return nil
